# Search for key markers
for term in ["[grade]", "[grader tail]", "[facts]", "[first wrong step]", "[request]", "[checkpoint"]:
    results = await CONTEXT.search(term)
    print(f"\n{term}: type={type(results)}, len={len(results) if hasattr(results, '__len__') else 'N/A'}")
    if hasattr(results, '__getitem__'):
        for i in range(min(5, len(results))):
            print(f"  {i}: {results[i]}")
